    double risk_amount = balance * (risk_percent / 100.0);

    // 2. Calculate monetary loss per 1 LOT if price hits SL
    double profit_1_lot = 0;
    if(!OrderCalcProfit(order_type, symbol, 1.0, entry_price, sl_price, profit_1_lot))
    {
        Print("OrderCalcProfit error: ", GetLastError());
        return 0;
    }

    double loss_per_lot = MathAbs(profit_1_lot); // Always positive
    if(loss_per_lot <= 0 || risk_amount <= 0)
    {
        Print("Invalid loss calculation or risk amount");
        return 0;
    }

    // 3. Compute raw volume
    double volume = risk_amount / loss_per_lot;

    // 4. Normalize to symbol requirements
    double min_lot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double max_lot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lot_step = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    volume = MathMax(min_lot, MathMin(max_lot, MathFloor(volume / lot_step) * lot_step));

    // 5. Safety: Ensure volume > 0 after normalization
    return (volume >= min_lot) ? volume : 0;
}

